import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  zip: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    zip: '',
  });

  const setField = (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const isLastStep = step === STEPS.length - 1;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(data);
    } else {
      setStep((s) => Math.min(s + 1, STEPS.length - 1));
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: 420,
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={setField('name')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={setField('email')}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={setField('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Адрес"
            required
            value={data.address}
            onChange={setField('address')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={setField('city')}
          />
          <JxInputField
            label="Индекс"
            value={data.zip}
            onChange={setField('zip')}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <span style={{ fontFamily: 'var(--jx-font-sans)', color: 'var(--jx-text-2)', fontSize: 13 }}>
            Проверьте данные перед отправкой
          </span>
          {[
            ['Имя', data.name],
            ['Email', data.email],
            ['Телефон', data.phone],
            ['Адрес', data.address],
            ['Город', data.city],
            ['Индекс', data.zip],
          ].map(([label, value]) => (
            <div
              key={label}
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                gap: 'var(--jx-r)',
                padding: 'var(--jx-r-sm) 0',
                borderBottom: '1px solid var(--jx-rule)',
                fontFamily: 'var(--jx-font-sans)',
              }}
            >
              <span style={{ color: 'var(--jx-text-3)' }}>{label}</span>
              <span style={{ color: 'var(--jx-text)' }}>{value || '—'}</span>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((s) => Math.max(s - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

